  1	package agentusage
  2	
  3	import (
  4		"encoding/json"
  5		"errors"
  6		"io"
  7	)
  8	
  9	// State tells whether a sub-agent has finished.
 10	type State int
 11	
 12	const (
 13		StateUnknown State = iota
 14		StateFinished
 15		StateUnfinished
 16	)
 17	
 18	// meta is the subset of agent-<id>.meta.json that is read. The description
 19	// and worktree path keys are deliberately absent: they are never decoded.
 20	type meta struct {
 21		AgentType  string
 22		Finished   *bool
 23		SpawnDepth int
 24	}
 25	
 26	// wireMeta keeps agentType and spawnDepth raw: one of an unexpected type
 27	// costs that field only. finished stays typed, so a wrong type is an error.
 28	type wireMeta struct {
 29		AgentType  json.RawMessage `json:"agentType"`
 30		Finished   json.RawMessage `json:"finished"`
 31		SpawnDepth json.RawMessage `json:"spawnDepth"`
 32	}
 33	
 34	// maxMetaBytes is the largest meta file read; a bigger one is refused.
 35	const maxMetaBytes = 1 << 20
 36	
 37	// Fixed messages because encoding/json errors can quote file content.
 38	var (
 39		errMalformedMeta = errors.New("agentusage: malformed meta file")
 40		errMetaTooBig    = errors.New("agentusage: meta file too large")
 41		errMetaNotPlain  = errors.New("agentusage: meta file is not a regular file")
 42	)
 43	
 44	// readMeta reads a meta file. A missing file yields an error satisfying
 45	// errors.Is(err, os.ErrNotExist). A symbolic link or non-regular file is
 46	// refused, and reading is bounded by maxMetaBytes.
 47	func readMeta(path string) (meta, error) {
 48		f, err := openPlain(path, false)
 49		if err != nil {
 50			return meta{}, err
 51		}
 52		if f == nil {
 53			return meta{}, errMetaNotPlain
 54		}
 55		defer func() { _ = f.Close() }()
 56		b, err := io.ReadAll(io.LimitReader(f, maxMetaBytes+1))
 57		if err != nil {
 58			return meta{}, err
 59		}
 60		if len(b) > maxMetaBytes {
 61			return meta{}, errMetaTooBig
 62		}
 63		var w wireMeta
 64		if json.Unmarshal(b, &w) != nil {
 65			return meta{}, errMalformedMeta
 66		}
 67		m := meta{AgentType: optString(w.AgentType)}
 68		var fin bool
 69		if json.Unmarshal(w.Finished, &fin) == nil && string(w.Finished) != "null" {
 70			m.Finished = &fin // absent, null or a wrong type: stays nil
 71		}
 72		if len(w.SpawnDepth) > 0 {
 73			_ = json.Unmarshal(w.SpawnDepth, &m.SpawnDepth) // wrong type: stays 0
 74		}
 75		return m, nil
 76	}
 77	
 78	// state maps the finished flag; absent or null is StateUnknown.
 79	func (m meta) state() State {
 80		switch {
 81		case m.Finished == nil:
 82			return StateUnknown
 83		case *m.Finished:
 84			return StateFinished
 85		}
 86		return StateUnfinished
 87	}
 88	package agentusage
 89	
 90	import (
 91		"errors"
 92		"fmt"
 93		"io/fs"
 94		"os"
 95		"path/filepath"
 96		"sort"
 97		"strings"
 98	)
 99	
100	const (
101		transcriptExt = ".jsonl"
102		metaExt       = ".meta.json"
103		agentPrefix   = "agent-"
104		subagentsDir  = "subagents"
105	)
106	
107	// SubAgentFiles locates one sub-agent's files; Meta is "" if absent.
108	type SubAgentFiles struct{ ID, Transcript, Meta string }
109	
110	// SessionFiles locates a session's transcripts.
111	type SessionFiles struct {
112		ID, Parent string
113		SubAgents  []SubAgentFiles
114	}
115	
116	// ProjectsRoot returns the Claude Code projects directory:
117	// $CLAUDE_CONFIG_DIR/projects, else ~/.claude/projects.
118	func ProjectsRoot() (string, error) {
119		if dir := os.Getenv("CLAUDE_CONFIG_DIR"); dir != "" {
120			return filepath.Join(dir, "projects"), nil
121		}
122		home, err := os.UserHomeDir()
123		if err != nil {
124			return "", err
125		}
126		return filepath.Join(home, ".claude", "projects"), nil
127	}
128	
129	// LocateSession finds the sub-agent files of the session whose parent
130	// transcript is <dir>/<uuid>.jsonl, looking in <dir>/<uuid>/subagents/. A
131	// missing session directory means no sub-agents. Symbolic links are ignored
132	// and nothing is searched recursively.
133	func LocateSession(parentTranscript string) (SessionFiles, error) {
134		base := filepath.Base(parentTranscript)
135		if !strings.HasSuffix(base, transcriptExt) {
136			return SessionFiles{}, fmt.Errorf("agentusage: %s does not end in %s", base, transcriptExt)
137		}
138		info, err := os.Lstat(parentTranscript)
139		if err != nil {
140			return SessionFiles{}, baseOnly(err)
141		}
142		if !info.Mode().IsRegular() {
143			return SessionFiles{}, fmt.Errorf("agentusage: %s is not a regular file", base)
144		}
145		id := strings.TrimSuffix(base, transcriptExt)
146		files := SessionFiles{ID: id, Parent: parentTranscript}
147		sessionDir := filepath.Join(filepath.Dir(parentTranscript), id)
148		if fi, err := os.Lstat(sessionDir); err != nil || !fi.IsDir() {
149			if err == nil || errors.Is(err, os.ErrNotExist) {
150				return files, nil // absent, or a link: no sub-agents
151			}
152			return files, err
153		}
154		files.SubAgents, err = subAgentFiles(filepath.Join(sessionDir, subagentsDir))
155		return files, err
156	}
157	
158	// subAgentFiles lists agent-<id>.jsonl files directly inside dir, sorted by
159	// ID, each with its meta file if one exists. A missing dir or a symbolic
160	// link yields nothing.
161	func subAgentFiles(dir string) ([]SubAgentFiles, error) {
162		f, err := openPlain(dir, true)
163		if f == nil {
164			if err == nil || errors.Is(err, os.ErrNotExist) {
165				return nil, nil
166			}
167			return nil, err
168		}
169		defer func() { _ = f.Close() }()
170		entries, err := f.ReadDir(-1)
171		if err != nil {
172			return nil, err
173		}
174		var out []SubAgentFiles
175		for _, e := range entries {
176			if sa, ok := subAgentEntry(dir, e); ok {
177				out = append(out, sa)
178			}
179		}
180		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
181		return out, nil
182	}
183	
184	// subAgentEntry turns a directory entry into a sub-agent, if it is a
185	// regular agent-<id>.jsonl file.
186	func subAgentEntry(dir string, e os.DirEntry) (SubAgentFiles, bool) {
187		name := e.Name()
188		if !e.Type().IsRegular() || !strings.HasPrefix(name, agentPrefix) || !strings.HasSuffix(name, transcriptExt) {
189			return SubAgentFiles{}, false
190		}
191		id := strings.TrimSuffix(strings.TrimPrefix(name, agentPrefix), transcriptExt)
192		if id == "" {
193			return SubAgentFiles{}, false
194		}
195		sa := SubAgentFiles{ID: id, Transcript: filepath.Join(dir, name)}
196		metaPath := filepath.Join(dir, agentPrefix+id+metaExt)
197		if mf, _ := openPlain(metaPath, false); mf != nil {
198			_ = mf.Close()
199			sa.Meta = metaPath
200		}
201		return sa, true
202	}
203	
204	// baseOnly rewrites a path error so it names the base name of the file, not
205	// the full path; errors.Is and errors.As on the cause keep working.
206	func baseOnly(err error) error {
207		var pe *fs.PathError
208		if errors.As(err, &pe) {
209			return &fs.PathError{Op: pe.Op, Path: filepath.Base(pe.Path), Err: pe.Err}
210		}
211		return err
212	}
213	package agentusage
214	
215	import (
216		"errors"
217		"os"
218	)
219	
220	// errNotPlain is returned when a path is not what Lstat said it was a moment
221	// ago (swapped for a link or another file). It is fixed so it never carries
222	// a path or content.
223	var errNotPlain = errors.New("agentusage: path changed while being opened")
224	
225	// openPlain opens path only if it is not a symbolic link and its mode, as
226	// reported by Lstat, matches wantDir. The opened handle is compared with the
227	// Lstat result (os.SameFile), which closes the window between checking and
228	// opening. On Windows the file identity is read lazily, at the SameFile call. A missing path yields an error satisfying os.ErrNotExist; a path
229	// of the wrong kind yields (nil, nil).
230	func openPlain(path string, wantDir bool) (*os.File, error) {
231		li, err := os.Lstat(path)
232		if err != nil {
233			return nil, err
234		}
235		if li.IsDir() != wantDir || (!wantDir && !li.Mode().IsRegular()) {
236			return nil, nil
237		}
238		f, err := os.Open(path)
239		if err != nil {
240			return nil, err
241		}
242		fi, err := f.Stat()
243		if err != nil || !os.SameFile(li, fi) {
244			_ = f.Close()
245			if err == nil {
246				err = errNotPlain
247			}
248			return nil, err
249		}
250		return f, nil
251	}
252	package agentusage
253	
254	// Agent is the usage of one agent of a session: the orchestrator (Main) or a
255	// sub-agent.
256	type Agent struct {
257		ID              string
258		Main            bool
259		Type            string // sub-agent type from its meta file; "" if unknown
260		Models          []string
261		Tokens          Tokens
262		Messages        int // distinct message ids
263		PartialMessages int // messages whose last line has no stop reason
264		State           State
265		SpawnDepth      int
266	}
267	
268	// PartialOutput reports whether some message of the agent was still being
269	// written (no stop reason on its last line), so its output count is a floor.
270	func (a Agent) PartialOutput() bool { return a.PartialMessages > 0 }
271	
272	// IssueKind classifies a line that could not be counted.
273	type IssueKind int
274	
275	const (
276		IssueUnreadable IssueKind = iota // not JSON, truncated, or bad counters
277		IssueOversized                   // longer than MaxLineBytes
278		IssueOpenFailed                  // a sub-agent transcript could not be opened
279	)
280	
281	// FileIssue locates one skipped line. File is a base name, never a path.
282	type FileIssue struct {
283		File   string
284		Offset int64
285		Kind   IssueKind
286	}
287	
288	// Diagnostics counts what parsing skipped or had to guess.
289	type Diagnostics struct {
290		UnreadableLines     int
291		OversizedLines      int
292		NoUsage             int
293		NoMessageID         int
294		CrossFileDuplicates int
295		MetaMissing         int
296		MetaUnreadable      int
297		TruncatedFiles      []string
298		Files               []FileIssue
299	}
300	
301	// Degraded reports whether anything was skipped or guessed.
302	func (d Diagnostics) Degraded() bool {
303		return d.UnreadableLines > 0 || d.OversizedLines > 0 || d.NoUsage > 0 ||
304			d.NoMessageID > 0 || d.CrossFileDuplicates > 0 || d.MetaMissing > 0 ||
305			d.MetaUnreadable > 0 || len(d.TruncatedFiles) > 0 || len(d.Files) > 0
306	}
307	
308	// Usage is the parsed usage of one session.
309	type Usage struct {
310		SessionID   string
311		Agents      []Agent
312		Versions    []string
313		Diagnostics Diagnostics
314	}
315	
316	// Total returns the tokens of every agent.
317	func (u Usage) Total() Tokens {
318		var t Tokens
319		for _, a := range u.Agents {
320			t = t.Add(a.Tokens)
321		}
322		return t
323	}
324	// Package agentusage reads coding-agent usage logs. It is pure stdlib and
325	// has no dependency on the UI.
326	package agentusage
327	
328	import "math"
329	
330	// Tokens counts the tokens of one or more agent requests.
331	type Tokens struct {
332		Input      int64
333		Output     int64
334		CacheRead  int64
335		CacheWrite int64
336	}
337	
338	// Total returns the sum of the four counters, saturating at math.MaxInt64.
339	func (t Tokens) Total() int64 {
340		return satAdd(satAdd(t.Input, t.Output), satAdd(t.CacheRead, t.CacheWrite))
341	}
342	
343	// Add returns the field-wise sum of t and o, each field saturating at
344	// math.MaxInt64.
345	func (t Tokens) Add(o Tokens) Tokens {
346		return Tokens{
347			Input:      satAdd(t.Input, o.Input),
348			Output:     satAdd(t.Output, o.Output),
349			CacheRead:  satAdd(t.CacheRead, o.CacheRead),
350			CacheWrite: satAdd(t.CacheWrite, o.CacheWrite),
351		}
352	}
353	
354	// satAdd adds two non-negative counters without wrapping.
355	func satAdd(a, b int64) int64 {
356		if a > math.MaxInt64-b {
357			return math.MaxInt64
358		}
359		return a + b
360	}

