  1	package agentusage
  2	
  3	import (
  4		"path/filepath"
  5		"sort"
  6	)
  7	
  8	// ParseSession aggregates the usage of every agent of a session. It fails
  9	// only if the parent transcript cannot be opened; a sub-agent that cannot be
 10	// read stays in Agents with no tokens and a FileIssue.
 11	func ParseSession(files SessionFiles) (Usage, error) {
 12		subs := append([]SubAgentFiles(nil), files.SubAgents...)
 13		sort.Slice(subs, func(i, j int) bool { return subs[i].ID < subs[j].ID })
 14		agg := newAggregator([]Agent{{Main: true, State: StateUnknown}})
 15		if err := parseFile(agg, 0, files.Parent); err != nil {
 16			return Usage{}, baseOnly(err)
 17		}
 18		for _, sa := range subs {
 19			agg.agents = append(agg.agents, agentFromMeta(&agg.diag, sa))
 20			if err := parseFile(agg, len(agg.agents)-1, sa.Transcript); err != nil {
 21				agg.diag.Files = append(agg.diag.Files, FileIssue{File: filepath.Base(sa.Transcript), Kind: IssueOpenFailed})
 22			}
 23		}
 24		return Usage{
 25			SessionID:   files.ID,
 26			Agents:      agg.finish(),
 27			Versions:    agg.versions(),
 28			Diagnostics: agg.diag,
 29		}, nil
 30	}
 31	
 32	// agentFromMeta builds a sub-agent's identity from its meta file, counting
 33	// a missing or unreadable one in diag.
 34	func agentFromMeta(diag *Diagnostics, sa SubAgentFiles) Agent {
 35		ag := Agent{ID: sa.ID}
 36		if sa.Meta == "" {
 37			diag.MetaMissing++
 38			return ag
 39		}
 40		m, err := readMeta(sa.Meta)
 41		if err != nil {
 42			diag.MetaUnreadable++
 43			return ag
 44		}
 45		ag.Type, ag.State, ag.SpawnDepth = m.AgentType, m.state(), m.SpawnDepth
 46		return ag
 47	}
 48	
 49	// parseFile folds one transcript into the aggregator for agent idx. It
 50	// fails only if the file cannot be opened.
 51	func parseFile(agg *aggregator, idx int, path string) error {
 52		f, err := openPlain(path, false)
 53		if err != nil {
 54			return err
 55		}
 56		if f == nil {
 57			return errNotPlain
 58		}
 59		defer func() { _ = f.Close() }()
 60		name := filepath.Base(path)
 61		res, err := scanLines(f, MaxLineBytes, func(line []byte, off int64) {
 62			agg.addLine(idx, name, off, line)
 63		})
 64		for _, off := range res.OversizedAt {
 65			agg.diag.OversizedLines++
 66			agg.diag.Files = append(agg.diag.Files, FileIssue{File: name, Offset: off, Kind: IssueOversized})
 67		}
 68		if err != nil {
 69			// A read error mid-file: what was read still counts.
 70			agg.diag.UnreadableLines++
 71			agg.diag.Files = append(agg.diag.Files, FileIssue{File: name, Offset: res.Consumed, Kind: IssueUnreadable})
 72		}
 73		if len(res.Tail) > 0 {
 74			agg.diag.TruncatedFiles = append(agg.diag.TruncatedFiles, name)
 75		}
 76		return nil
 77	}
 78	package agentusage
 79	
 80	import (
 81		"encoding/json"
 82		"strconv"
 83	)
 84	
 85	// lineKind classifies one transcript line.
 86	type lineKind int
 87	
 88	const (
 89		kindUsage      lineKind = iota // message.usage present: counts
 90		kindNoUsage                    // message with an id, but no usage object
 91		kindIgnored                    // valid JSON without a message, or a message with neither id nor usage
 92		kindUnreadable                 // not JSON, truncated, or bad counters
 93		kindSynthetic                  // model "<synthetic>": never counts
 94	)
 95	
 96	// record is what decodeLine extracts from a line; only these fields are read.
 97	type record struct {
 98		MessageID string
 99		Model     string
100		Version   string
101		Usage     Tokens
102		StopNull  bool
103	}
104	
105	// syntheticModel is the model name of locally generated, never-billed turns.
106	const syntheticModel = "<synthetic>"
107	
108	// wireLine mirrors the only keys read from a transcript line. Content,
109	// tools and descriptions are deliberately not declared, so encoding/json
110	// skips them without keeping them. The root "type" key is not consulted.
111	type wireLine struct {
112		Version json.RawMessage `json:"version"`
113		Message *wireMessage    `json:"message"`
114	}
115	
116	type wireMessage struct {
117		ID         string          `json:"id"`
118		Model      json.RawMessage `json:"model"`
119		StopReason json.RawMessage `json:"stop_reason"`
120		Usage      *wireUsage      `json:"usage"`
121	}
122	
123	// wireUsage keeps counters raw so a negative, fractional or non-numeric
124	// value can be told apart from an absent one.
125	type wireUsage struct {
126		Input      json.RawMessage `json:"input_tokens"`
127		Output     json.RawMessage `json:"output_tokens"`
128		CacheRead  json.RawMessage `json:"cache_read_input_tokens"`
129		CacheWrite json.RawMessage `json:"cache_creation_input_tokens"`
130	}
131	
132	// decodeLine extracts the usage fields of one transcript line. A message
133	// without usage counts as kindNoUsage only if it has an id (an assistant
134	// turn whose usage went missing or was renamed). It never
135	// reports a decoder error: those can quote line content, so a bad line is
136	// just kindUnreadable.
137	func decodeLine(b []byte) (record, lineKind) {
138		var w wireLine
139		if err := json.Unmarshal(b, &w); err != nil {
140			return record{}, kindUnreadable
141		}
142		m := w.Message
143		if m == nil {
144			return record{Version: optString(w.Version)}, kindIgnored
145		}
146		rec := record{
147			MessageID: m.ID,
148			Model:     optString(m.Model),
149			Version:   optString(w.Version),
150			StopNull:  isNullOrAbsent(m.StopReason),
151		}
152		switch {
153		case rec.Model == syntheticModel:
154			return rec, kindSynthetic
155		case m.Usage == nil && m.ID == "":
156			// User and tool-result lines carry a message without id or usage.
157			return rec, kindIgnored
158		case m.Usage == nil:
159			return rec, kindNoUsage
160		}
161		tokens, ok := m.Usage.tokens()
162		if !ok {
163			return record{}, kindUnreadable
164		}
165		rec.Usage = tokens
166		return rec, kindUsage
167	}
168	
169	// tokens converts the raw counters; ok is false if any is not a
170	// non-negative integer.
171	func (u *wireUsage) tokens() (Tokens, bool) {
172		var t Tokens
173		for _, c := range []struct {
174			raw json.RawMessage
175			dst *int64
176		}{{u.Input, &t.Input}, {u.Output, &t.Output}, {u.CacheRead, &t.CacheRead}, {u.CacheWrite, &t.CacheWrite}} {
177			n, ok := parseCounter(c.raw)
178			if !ok {
179				return Tokens{}, false
180			}
181			*c.dst = n
182		}
183		return t, true
184	}
185	
186	// parseCounter reads one counter; absent or null is 0.
187	func parseCounter(raw json.RawMessage) (int64, bool) {
188		if len(raw) == 0 || string(raw) == "null" {
189			return 0, true
190		}
191		n, err := strconv.ParseInt(string(raw), 10, 64)
192		return n, err == nil && n >= 0
193	}
194	
195	// optString returns the JSON string held by raw, or "" if raw is absent or
196	// of another type: metadata of an unexpected type must not cost the line.
197	func optString(raw json.RawMessage) string {
198		var s string
199		if len(raw) == 0 || raw[0] != '"' || json.Unmarshal(raw, &s) != nil {
200			return ""
201		}
202		return s
203	}
204	
205	// isNullOrAbsent reports whether raw is a missing key or a JSON null. Any
206	// other value, whatever its type, counts as a stop reason being set.
207	func isNullOrAbsent(raw json.RawMessage) bool {
208		return len(raw) == 0 || string(raw) == "null"
209	}
210	package agentusage
211	
212	// msgKey identifies one message of a session. A message with an id is keyed
213	// by the id alone; one without is keyed by where it was read.
214	type msgKey struct {
215		id   string
216		file string
217		off  int64
218	}
219	
220	// entry is the last state seen of one message.
221	type entry struct {
222		agent    int
223		file     string
224		model    string
225		tokens   Tokens
226		stopNull bool
227	}
228	
229	// aggregator folds records into per-agent totals, last line wins per
230	// message id. Agents must be added in a fixed order (parent, then
231	// sub-agents by ID); a message seen in several files goes to the last.
232	type aggregator struct {
233		agents  []Agent
234		diag    Diagnostics
235		entries map[msgKey]*entry
236		order   []msgKey // first appearance, for stable model order
237		seen    map[string]bool
238		version []string // distinct versions, first appearance order
239	}
240	
241	// newAggregator starts from agents carrying their identity (ID, Main, Type,
242	// State, SpawnDepth); the counters are filled by add and finish.
243	func newAggregator(agents []Agent) *aggregator {
244		return &aggregator{agents: agents, entries: map[msgKey]*entry{}, seen: map[string]bool{}}
245	}
246	
247	// addLine decodes one line of agent agentIdx's file (file is a base name) and folds it in,
248	// counting what is skipped. Synthetic and ignored lines never count.
249	func (a *aggregator) addLine(agentIdx int, file string, off int64, line []byte) {
250		r, kind := decodeLine(line)
251		if kind != kindUnreadable {
252			a.noteVersion(r.Version)
253		}
254		switch kind {
255		case kindUsage:
256			a.add(agentIdx, file, off, r)
257		case kindNoUsage:
258			a.diag.NoUsage++
259		case kindUnreadable:
260			a.diag.UnreadableLines++
261			a.diag.Files = append(a.diag.Files, FileIssue{File: file, Offset: off, Kind: IssueUnreadable})
262		case kindIgnored, kindSynthetic:
263		}
264	}
265	
266	// noteVersion records a client version the first time it is seen.
267	func (a *aggregator) noteVersion(v string) {
268		if v == "" || a.seen[v] {
269			return
270		}
271		a.seen[v] = true
272		a.version = append(a.version, v)
273	}
274	
275	// versions returns the distinct versions seen, in order of first appearance.
276	func (a *aggregator) versions() []string { return a.version }
277	
278	// add folds one usage record in. file and off identify the line when the
279	// record has no message id.
280	func (a *aggregator) add(agentIdx int, file string, off int64, r record) {
281		key := msgKey{id: r.MessageID}
282		if r.MessageID == "" {
283			key = msgKey{file: file, off: off}
284			a.diag.NoMessageID++
285		}
286		e, ok := a.entries[key]
287		if !ok {
288			e = &entry{}
289			a.entries[key] = e
290			a.order = append(a.order, key)
291		} else if e.file != file {
292			a.diag.CrossFileDuplicates++
293		}
294		*e = entry{agent: agentIdx, file: file, model: r.Model, tokens: r.Usage, stopNull: r.StopNull}
295	}
296	
297	// finish returns the agents with Tokens, Models, Messages and
298	// PartialMessages computed.
299	func (a *aggregator) finish() []Agent {
300		for i := range a.agents {
301			a.agents[i].Tokens, a.agents[i].Models = Tokens{}, nil
302			a.agents[i].Messages, a.agents[i].PartialMessages = 0, 0
303		}
304		for _, key := range a.order {
305			e := a.entries[key]
306			ag := &a.agents[e.agent]
307			ag.Tokens = ag.Tokens.Add(e.tokens)
308			ag.Messages++
309			if e.stopNull {
310				ag.PartialMessages++
311			}
312			ag.addModel(e.model)
313		}
314		return a.agents
315	}
316	
317	// addModel appends model unless it is empty or already listed.
318	func (ag *Agent) addModel(model string) {
319		if model == "" {
320			return
321		}
322		for _, m := range ag.Models {
323			if m == model {
324				return
325			}
326		}
327		ag.Models = append(ag.Models, model)
328	}
