     3	import (
     4		"bytes"
     5		"fmt"
     6		"os"
     7		"path/filepath"
     8		"reflect"
     9		"strings"
    10		"testing"
    11	)
    12	
    13	// fixtureSession locates the single session of testdata/<name>.
    14	func fixtureSession(t *testing.T, name string) SessionFiles {
    15		t.Helper()
    16		parents, err := filepath.Glob(filepath.Join("testdata", name, "projects", "*", "*.jsonl"))
    17		if err != nil || len(parents) != 1 {
    18			t.Fatalf("fixture %s: parents = %v, err %v", name, parents, err)
    19		}
    20		files, err := LocateSession(parents[0])
    21		if err != nil {
    22			t.Fatalf("LocateSession: %v", err)
    23		}
    24		return files
    25	}
    26	
    27	func parseFixture(t *testing.T, name string) Usage {
    28		t.Helper()
    29		u, err := ParseSession(fixtureSession(t, name))
    30		if err != nil {
    31			t.Fatalf("ParseSession(%s): %v", name, err)
    32		}
    33		return u
    34	}
    35	
    36	// Expected values below are computed by hand from testdata/v2.1.302-basic.
    37	func TestParseSessionBasic(t *testing.T) {
    38		u := parseFixture(t, "v2.1.302-basic")
    39		if u.SessionID != "00000000-0000-4000-8000-000000000302" {
    40			t.Errorf("SessionID = %q", u.SessionID)
    41		}
    42		want := []Agent{
    43			{ID: "", Main: true, State: StateUnknown, Type: "", Tokens: Tokens{13, 320, 1200, 1050}, Messages: 2, Models: []string{"model-alpha"}},
    44			{ID: "a01", Type: "coder", State: StateFinished, SpawnDepth: 1, Tokens: Tokens{9, 140, 1400, 200}, Messages: 2, Models: []string{"model-beta"}},
    45			{ID: "a02", Type: "tester", State: StateUnfinished, SpawnDepth: 1, Tokens: Tokens{5, 38, 2000, 300}, Messages: 2, PartialMessages: 1, Models: []string{"model-beta"}},
    46			{ID: "a03", Type: "reviewer", State: StateFinished, SpawnDepth: 2, Tokens: Tokens{6, 90, 40, 10}, Messages: 1, Models: []string{"model-gamma"}},
    47		}
    48		// Criterion 1: four agents, four exact totals each.
    49		if len(u.Agents) != len(want) {
    50			t.Fatalf("agents = %d, want %d: %+v", len(u.Agents), len(want), u.Agents)
